![high](https://www.gstatic.com/codereviewagent/high-priority.svg)

In the new append-only architecture, applying ledger overlays unconditionally at the end of `readDebtRecords` will prevent reopened threads from being correctly marked as `open`. If a thread is marked `done` in `ledger.jsonl` but subsequently re-harvested in a newer harvest file, the overlay will overwrite its status back to `done`.

To fix this, we should only apply terminal overlays (`done` or `wontfix`) if the record's `harvested_at` timestamp is less than or equal to the overlay's `fixed_at` timestamp.

```typescript
function applyLedgerOverlays(records: DebtRecord[]): DebtRecord[] {
  const overlays = readLedgerOverlays();
  if (overlays.size === 0) {
    return records;
  }
  return records.map((row) => {
    const overlay = overlays.get(row.thread_id);
    if (!overlay) {
      return row;
    }
    if (
      (overlay.status === "done" || overlay.status === "wontfix") &&
      overlay.fixed_at &&
      row.harvested_at > overlay.fixed_at
    ) {
      return row;
    }
    return {
      ...row,
      status: overlay.status,
      fix_pr: overlay.fix_pr,
      fixed_at: overlay.fixed_at,
      notes: overlay.notes,
    };
  });
}
```

![high](https://www.gstatic.com/codereviewagent/high-priority.svg)

Currently, `legacy` is appended to the end of `sources`, meaning it is processed last in `readDebtRecords`. This causes older statuses from the legacy file to overwrite newer statuses from recent harvest files in `upsertRecords`.

To ensure correct chronological merging, `legacy` should be processed first as the baseline, followed by the newer harvest files.

```suggestion
export function readDebtRecords(): DebtRecord[] {
  const sources: string[] = [];
  const legacy = debtFile();
  if (existsSync(legacy)) {
    sources.push(legacy);
  }
  sources.push(...listHarvestFiles());

  let merged: DebtRecord[] = [];
  for (const file of sources) {
    merged = upsertRecords(merged, readJsonlLines<DebtRecord>(file));
  }
  return applyLedgerOverlays(merged);
}
```

![medium](https://www.gstatic.com/codereviewagent/medium-priority.svg)

Let's expand this test to verify that a newer harvest file correctly reopens a thread that was previously marked as `done` in the ledger overlay.

```typescript
  test("readDebtRecords merges harvest files and ledger overlay", () => {
    const dir = mkdtempSync(join(tmpdir(), "debt-harvest-"));
    const prevDir = process.env.OPENADT_DEBT_DIR;
    process.env.OPENADT_DEBT_DIR = dir;
    try {
      const row = sampleDebtRecord();
      writeHarvestFile({
        pr: 1,
        runId: "run1",
        harvestedAt: "2026-01-01T00:00:00Z",
        records: [row],
      });
      upsertLedgerOverlays([
        {
          thread_id: "PRRT_1",
          status: "done",
          fix_pr: 99,
          fixed_at: "2026-02-01T00:00:00Z",
          notes: null,
        },
      ]);
      const merged = readDebtRecords();
      expect(merged).toHaveLength(1);
      expect(merged[0]?.status).toBe("done");
      expect(merged[0]?.fix_pr).toBe(99);

      // Verify that a newer harvest file correctly reopens the thread
      writeHarvestFile({
        pr: 1,
        runId: "run2",
        harvestedAt: "2026-03-01T00:00:00Z",
        records: [row],
      });
      const reopened = readDebtRecords();
      expect(reopened).toHaveLength(1);
      expect(reopened[0]?.status).toBe("open");
      expect(reopened[0]?.fix_pr).toBeNull();
    } finally {
      if (prevDir === undefined) {
        delete process.env.OPENADT_DEBT_DIR;
      } else {
        process.env.OPENADT_DEBT_DIR = prevDir;
      }
      rmSync(dir, { recursive: true, force: true });
    }
  });
```

